"""Variables excluded for leakage/ethics/proxy reasons: explicit list with rationale, and a test that no model uses them (23/10).
Run: MODEL_FEATURES=results_s3/features_used.txt PYTHONPATH=src python3 -m pytest hackathon_checks/tests/test_excluded_features.py -q
MODEL_FEATURES: one variable per line, exported from prepare.allowed_features (scripts/export_features.py)."""
import json, os
from pathlib import Path
import pytest

EXCLUDED = {
    "customer_service_contacts": "leakage: generated by claims (also unreported ones); in the test set it has the distribution of rows without claims — used only as a signal of late claims in the history (experience.history_fix)",
    "renewal_decision": "leakage: decided after the period, absent from the test set",
    "written_premium": "circular in Part 1: current tariff, benchmark only (in Part 2 only prem_rel enters the motor correction, see report §5)",
    "row_id": "id", "policy_id": "id", "customer_id": "id (history only)", "address_id": "id (history only)", "claim_id": "id",
    "surname": "ethnicity proxy / no risk rationale", "email_domain": "no risk rationale",
    "date_of_birth": "replaced by age", "birth_year": "replaced by age", "construction_type_raw": "raw, replaced by the cleaned version",
}
FEATURES_FILE = os.environ.get("MODEL_FEATURES")


def _features():
    txt = Path(FEATURES_FILE).read_text()
    try:
        return set(json.loads(txt))
    except json.JSONDecodeError:
        return {l.strip() for l in txt.splitlines() if l.strip()}


@pytest.mark.skipif(not FEATURES_FILE, reason="set MODEL_FEATURES")
def test_no_excluded_feature_used():
    used = _features()
    bad = sorted(f for f in used if f.lower() in EXCLUDED)
    assert not bad, f"excluded variables used by the model: {bad}"


def test_every_exclusion_has_reason():
    assert all(v.strip() for v in EXCLUDED.values())


def test_consistent_with_pipeline_lists():
    try:
        import prepare  # noqa: F401
    except Exception:
        pytest.skip("pipeline not importable (set PYTHONPATH=src)")
    forbidden = {str(x).lower() for x in getattr(prepare, "FORBIDDEN", [])}
    missing = {"customer_service_contacts", "renewal_decision", "written_premium"} - forbidden
    assert not missing, f"missing from prepare.FORBIDDEN: {missing}"
